import math


def largest_value_window(values: list[float], span: float) -> int:
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if isinstance(span, bool) or not isinstance(span, (int, float)):
        raise TypeError("span must be numeric")
    if not math.isfinite(span):
        raise ValueError("span must be finite")
    if span < 0:
        raise ValueError("span must be non-negative")

    ordered = []
    for value in values:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("values must be numeric")
        if not math.isfinite(value):
            raise ValueError("values must be finite")
        ordered.append(value)
    ordered.sort()

    best = 0
    left = 0
    for right, value in enumerate(ordered):
        while left <= right and value - ordered[left] >= span:
            left += 1
        best = max(best, right - left + 1)
    return best

